    this.qualityName = opts.quality && QUALITY[opts.quality] ? opts.quality : detectQuality();
    this._qualityOverrides = opts.qualityOverrides || null;
    this.quality = Object.assign({}, QUALITY[this.qualityName], this._qualityOverrides || {});
    this.maxPixelRatio = opts.maxPixelRatio || 2;

    this.width = 1; this.height = 1;
    this.time = 0;
    this.shaders = new Map();
    this.fullscreen = new FullscreenTri(gl);

    /* --- environment --- */
    this.sun = {
      direction: new Vec3(0.45, 0.72, 0.53).normalize(),
      color: new Vec3(1.0, 0.94, 0.84),
      intensity: 3.4,
    };
    this.sky = {
      zenith: new Vec3(0.16, 0.33, 0.66),
      horizon: new Vec3(0.62, 0.74, 0.88),
      ground: new Vec3(0.26, 0.24, 0.22),
      intensity: 1.0,
      clouds: 0.4,
    };
    this.fog = {
      color: new Vec3(0.62, 0.72, 0.85),
      density: 0.008,
      height: 0,
      falloff: 0.08,
    };
    this.shadows = { enabled: true, distance: 60, strength: 0.86, split: 14 };
    this.post = {
      exposure: 1.0,
      /* The average scene luminance this grade was built around — an
         open daylight frame. Measured, not guessed: see
         survivor/test/_light.js, which prints it. Zero turns
         adaptation off and pins the exposure. */
      autoKey: 0.0,
      autoMin: 0.45,
      autoMax: 3.2,
      // Fraction of the way to the measured level per frame, at 60 Hz.
      adaptUp: 0.045,     // toward brighter: about a third of a second
      adaptDown: 0.012,   // toward darker: about one and a half seconds
      bloom: 0.55,
      bloomThreshold: 1.1,
      vignette: 0.55,
      chromatic: 0.0018,
      saturation: 1.08,
      contrast: 1.04,
      grain: 0.012,
    };
